import os
import re
import unicodedata
import hashlib
import hmac
import secrets
import mimetypes
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs, unquote
from pathlib import PurePosixPath
import html
import time
import threading
import json

# Configuration
TEMPLATE_DIR = '/srv/templates'
STATIC_DIR = '/srv/static'
SESSION_SECRET = secrets.token_bytes(32)
MAX_INCLUDE_DEPTH = 10
_sessions = {}
_sessions_lock = threading.Lock()


def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)


def create_session(username, role='viewer'):
    sid = secrets.token_hex(32)
    token = hmac.new(SESSION_SECRET, sid.encode(), hashlib.sha256).hexdigest()
    with _sessions_lock:
        _sessions[sid] = {
            'username': username,
            'role': role,
            'created': time.time(),
            'token': token
        }
    return sid, token


def validate_session(sid, token):
    with _sessions_lock:
        session = _sessions.get(sid)
    if not session:
        return None
    expected = hmac.new(SESSION_SECRET, sid.encode(), hashlib.sha256).hexdigest()
    if not constant_time_compare(token, expected):
        return None
    if time.time() - session['created'] > 3600:
        with _sessions_lock:
            _sessions.pop(sid, None)
        return None
    return session


def sanitize_path_component(component):
    """Remove dangerous characters from a single path component."""
    # Strip null bytes
    component = component.replace('\x00', '')
    # Reject components that are . or ..
    if component in ('.', '..'):
        return None
    # Reject if contains path separators
    if '/' in component or '\\' in component:
        return None
    return component


def resolve_template_path(template_name, base_dir=TEMPLATE_DIR):
    """Safely resolve a template path within the base directory.

    Security: validates path components to prevent directory traversal.
    Uses allowlist approach - only permits alphanumeric, dash, underscore, dot.
    """
    # URL-decode the template name
    decoded = unquote(template_name)

    # Normalize Unicode to NFC form FIRST for consistent handling
    # This prevents bypass via Unicode sequences that normalize to traversal patterns
    normalized = unicodedata.normalize('NFC', decoded)

    # Security check: reject traversal patterns AFTER normalization
    if '..' in normalized:
        raise ValueError(f"Directory traversal detected: {template_name}")
    if normalized.startswith('/'):
        raise ValueError(f"Absolute path rejected: {template_name}")

    # Split into components and validate each
    parts = normalized.split('/')
    clean_parts = []
    for part in parts:
        if not part:
            continue
        cleaned = sanitize_path_component(part)
        if cleaned is None:
            raise ValueError(f"Invalid path component: {part}")
        clean_parts.append(cleaned)

    if not clean_parts:
        raise ValueError("Empty template path")

    # Construct the full path
    full_path = os.path.join(base_dir, *clean_parts)

    # Final realpath check
    real_path = os.path.realpath(full_path)
    real_base = os.path.realpath(base_dir)

    if not real_path.startswith(real_base + os.sep) and real_path != real_base:
        raise ValueError(f"Path escapes base directory: {template_name}")

    return real_path


def process_template_includes(content, depth=0, base_dir=TEMPLATE_DIR):
    """Process {% include 'filename' %} directives in templates."""
    if depth > MAX_INCLUDE_DEPTH:
        return '<!-- max include depth exceeded -->'

    include_pattern = re.compile(r'\{%\s*include\s+[\'"](.+?)[\'"]\s*%\}')

    def replace_include(match):
        inc_path = match.group(1)
        try:
            resolved = resolve_template_path(inc_path, base_dir)
            if os.path.isfile(resolved):
                with open(resolved, 'r', encoding='utf-8') as f:
                    inc_content = f.read()
                return process_template_includes(inc_content, depth + 1, base_dir)
            else:
                return f'<!-- include not found: {html.escape(inc_path)} -->'
        except (ValueError, OSError) as e:
            return f'<!-- include error: {html.escape(str(e))} -->'

    return include_pattern.sub(replace_include, content)


def render_template(template_name, context=None, base_dir=TEMPLATE_DIR):
    """Render a template with variable substitution and includes."""
    if context is None:
        context = {}

    resolved = resolve_template_path(template_name, base_dir)

    if not os.path.isfile(resolved):
        raise FileNotFoundError(f"Template not found: {template_name}")

    with open(resolved, 'r', encoding='utf-8') as f:
        content = f.read()

    # Process includes
    content = process_template_includes(content, base_dir=base_dir)

    # Simple variable substitution with auto-escaping
    var_pattern = re.compile(r'\{\{\s*(.+?)\s*\}\}')

    def replace_var(match):
        var_name = match.group(1).strip()
        if var_name.startswith('raw:'):
            # Explicit raw output (trusted content only)
            actual_name = var_name[4:].strip()
            return str(context.get(actual_name, ''))
        value = context.get(var_name, '')
        return html.escape(str(value))

    content = var_pattern.sub(replace_var, content)
    return content


class TemplateHandler(BaseHTTPRequestHandler):

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path
        params = parse_qs(parsed.query)

        if path == '/health':
            self._send_json({'status': 'ok', 'uptime': time.time()})
        elif path == '/login':
            self._handle_login_page()
        elif path.startswith('/view/'):
            self._handle_view(path[6:], params)
        elif path.startswith('/static/'):
            self._handle_static(path[8:])
        elif path == '/api/templates':
            self._handle_list_templates(params)
        else:
            self._send_error(404, 'Not Found')

    def do_POST(self):
        parsed = urlparse(self.path)
        if parsed.path == '/login':
            self._handle_login_submit()
        else:
            self._send_error(405, 'Method Not Allowed')

    def _handle_view(self, template_name, params):
        # Authenticate
        session = self._get_session()
        if not session:
            self._send_error(401, 'Unauthorized')
            return

        try:
            context = {
                'username': session['username'],
                'role': session['role'],
                'page_title': params.get('title', ['Untitled'])[0],
                'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
            }
            content = render_template(template_name, context)
            self._send_html(content)
        except (ValueError, FileNotFoundError) as e:
            self._send_error(400, str(e))
        except Exception as e:
            self._send_error(500, 'Internal Server Error')

    def _handle_static(self, file_path):
        try:
            resolved = resolve_template_path(file_path, STATIC_DIR)
            if not os.path.isfile(resolved):
                self._send_error(404, 'Not Found')
                return
            mime_type = mimetypes.guess_type(resolved)[0] or 'application/octet-stream'
            with open(resolved, 'rb') as f:
                data = f.read()
            self.send_response(200)
            self.send_header('Content-Type', mime_type)
            self.send_header('Content-Length', str(len(data)))
            self.send_header('X-Content-Type-Options', 'nosniff')
            self.end_headers()
            self.wfile.write(data)
        except (ValueError, OSError):
            self._send_error(403, 'Forbidden')

    def _handle_login_page(self):
        self._send_html('<html><body><form method="POST" action="/login">'
                       '<input name="user"><input name="pass" type="password">'
                       '<button>Login</button></form></body></html>')

    def _handle_login_submit(self):
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 4096:
            self._send_error(413, 'Too Large')
            return
        body = self.rfile.read(content_length).decode('utf-8')
        params = parse_qs(body)
        username = params.get('user', [''])[0]
        password = params.get('pass', [''])[0]

        # In production: verify against secure credential store with argon2
        if self._verify_credentials(username, password):
            sid, token = create_session(username, 'viewer')
            self.send_response(302)
            self.send_header('Set-Cookie', f'sid={sid}; HttpOnly; SameSite=Strict')
            self.send_header('Set-Cookie', f'token={token}; HttpOnly; SameSite=Strict')
            self.send_header('Location', '/view/index.html')
            self.end_headers()
        else:
            self._send_error(401, 'Invalid credentials')

    def _verify_credentials(self, username, password):
        # Stub: in production use argon2id verification
        return username == 'demo' and constant_time_compare(password, 'demo123')

    def _handle_list_templates(self, params):
        session = self._get_session()
        if not session or session['role'] != 'admin':
            self._send_error(403, 'Forbidden')
            return
        templates = []
        for f in os.listdir(TEMPLATE_DIR):
            if os.path.isfile(os.path.join(TEMPLATE_DIR, f)):
                templates.append(f)
        self._send_json({'templates': templates})

    def _get_session(self):
        cookies = self.headers.get('Cookie', '')
        sid = None
        token = None
        for cookie in cookies.split(';'):
            cookie = cookie.strip()
            if cookie.startswith('sid='):
                sid = cookie[4:]
            elif cookie.startswith('token='):
                token = cookie[6:]
        if sid and token:
            return validate_session(sid, token)
        return None

    def _send_html(self, content):
        data = content.encode('utf-8')
        self.send_response(200)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.send_header('Content-Length', str(len(data)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('X-Frame-Options', 'DENY')
        self.end_headers()
        self.wfile.write(data)

    def _send_json(self, obj):
        data = json.dumps(obj).encode('utf-8')
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def _send_error(self, code, message):
        self.send_response(code)
        self.send_header('Content-Type', 'text/plain')
        self.end_headers()
        self.wfile.write(message.encode('utf-8'))

    def log_message(self, format, *args):
        pass  # Suppress default logging


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), TemplateHandler)
    print('Template server running on http://127.0.0.1:8080')
    server.serve_forever()
